param([string]$VictimVmName='XDR-Victim-Sprint18',[string]$CredentialPath='D:\VMs\XDR-Victim-Sprint18\victim-credential.xml')
$ErrorActionPreference='Stop';$root=Resolve-Path(Join-Path $PSScriptRoot '..\..');Set-Location $root
& (Join-Path $PSScriptRoot 'sprint28-final-reconciliation.ps1') -VictimVmName $VictimVmName -CredentialPath $CredentialPath
$base=Get-Content artifacts/sprint28-final-reconciliation.json -Raw|ConvertFrom-Json
function Sql($query){(docker exec deployment-postgres-1 psql -v ON_ERROR_STOP=1 -U platform -d platform -Atc $query).Trim()}
$ai=(Sql "select (select count(*) from platform.ai_policies)||'|'||(select count(*) from platform.ai_conversations)||'|'||(select count(*) from platform.ai_evidence_packages)||'|'||(select count(*) from platform.ai_messages)||'|'||(select count(*) from platform.ai_note_drafts)||'|'||(select count(*) from platform.ai_audit);").Split('|')|ForEach-Object{[long]$_}
$report=[ordered]@{schemaVersion='sprint30-final-reconciliation.v1';capturedAt=[DateTimeOffset]::UtcNow.ToString('o');postgres=$base.postgres;openSearch=$base.openSearch;differences=$base.differences;ai=[ordered]@{policies=$ai[0];conversations=$ai[1];evidencePackages=$ai[2];messages=$ai[3];noteDrafts=$ai[4];auditEvents=$ai[5]};victimQueues=$base.victimQueues;queueTotal=$base.queueTotal;responseNonterminal=$base.responseNonterminal;orchestrationPending=$base.orchestrationPending;updatePending=$base.updatePending;outbox=$base.outbox;nats=$base.nats;ha=$base.ha;objects=$base.objects;transfers=$base.transfers;passed=$base.passed-and$ai[1]-gt0-and$ai[2]-gt0-and$ai[3]-gt0-and$ai[5]-gt0}
$report|ConvertTo-Json -Depth 20|Set-Content artifacts/sprint30-final-reconciliation.json -Encoding utf8;$report|ConvertTo-Json -Depth 20;if(-not$report.passed){throw 'Sprint 30 final reconciliation failed.'}
